-- Hansot PriceGapDB import / generated from 2026-11-15 collected files
-- Existing schema: brand, platform, menu, delivery_price. No CREATE TABLE.
-- CHECK: MySQL 5.7/8.0 with utf8mb4, run on backed-up database.
-- SOURCE: official store price 115; Sangam Yogiyo 113; user-verified Guro 1; default 1.
-- Assumption approved by project: Baemin and CoupangEats follow observed Yogiyo price.
-- This is NOT an independent Baemin/CoupangEats price survey; provenance is tagged in store_name.
-- For pre-existing directly researched prices from other stores, do not overwrite.
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Brand name lookup / insert
ON DUPLICATE KEY UPDATE `food_type`=VALUES(`food_type`), `homepage`=VALUES(`homepage`), `checked_on`=VALUES(`checked_on`);

-- 2. Required 4 platforms: do not change already configured default_markup
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`);

-- 3. Official 115 menus. Upsert by UNIQUE(brand_id,name).
ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `store_price`=VALUES(`store_price`),
`size_info`=VALUES(`size_info`), `image`=VALUES(`image`);

-- 4. Initialize ONLY missing delivery rows, dynamically using platform.default_markup.
-- Existing manually researched rows are not modified by this step.
SELECT m.`menu_id`,p.`platform_id`,m.`store_price`+p.`default_markup`,NULL,1,NULL,NULL
FROM `menu` m JOIN `brand` b ON b.`brand_id`=m.`brand_id`
CROSS JOIN `platform` p
WHERE b.`name`='한솥도시락' AND p.`name` IN ('배달의민족','쿠팡이츠','요기요','자사앱')
AND NOT EXISTS (SELECT 1 FROM `delivery_price` dp WHERE dp.`menu_id`=m.`menu_id` AND dp.`platform_id`=p.`platform_id`);

-- 5. Yogiyo-observed 114 menus: 3 platforms each (342 rows).
-- Existing is_default=0 from another source is NOT overwritten;
-- defaults and same-store sources may be refreshed.
ON DUPLICATE KEY UPDATE
`price`=IF(`is_default`=1 OR `store_name`=VALUES(`store_name`),VALUES(`price`),`price`),
`delivery_fee`=IF(`is_default`=1 OR `store_name`=VALUES(`store_name`),VALUES(`delivery_fee`),`delivery_fee`),
`checked_on`=IF(`is_default`=1 OR `store_name`=VALUES(`store_name`),VALUES(`checked_on`),`checked_on`),
`store_name`=IF(`is_default`=1 OR `store_name`=VALUES(`store_name`),VALUES(`store_name`),`store_name`),
`is_default`=0;

COMMIT;

-- 6. Verify target brand row counts (expected 115 menus / 460 delivery rows if 4 platforms).
SELECT b.`name`,COUNT(DISTINCT m.`menu_id`) AS `menu_count`,COUNT(dp.`platform_id`) AS `delivery_row_count`,
SUM(CASE WHEN dp.`is_default`=0 THEN 1 ELSE 0 END) AS `non_default_count`,
SUM(CASE WHEN dp.`is_default`=1 THEN 1 ELSE 0 END) AS `default_count`
FROM `brand` b JOIN `menu` m ON m.`brand_id`=b.`brand_id`
LEFT JOIN `delivery_price` dp ON dp.`menu_id`=m.`menu_id`
WHERE b.`name`='한솥도시락' GROUP BY b.`name`;

-- Note: final researched/default counts may differ if this database already has surveyed prices.
